const searchResult = $input.first().json;
const original = $('Limpiar Query').first().json;

let pmids = [];
if (searchResult.esearchresult && searchResult.esearchresult.idlist) {
  pmids = searchResult.esearchresult.idlist;
}

// Si no hay resultados, NO incluir pmids en el objeto
if (pmids.length === 0) {
  return [{
    json: { 
      ...original, 
      no_results: true, 
      analysis: 'No se encontraron artículos científicos relevantes.' 
      // IMPORTANTE: NO incluyas pmids aquí
    }
  }];
}

// Si hay resultados, incluir pmids
return [{
  json: { 
    ...original, 
    pmids: pmids, 
    pmid_list: pmids.join(','), 
    article_count: pmids.length 
  }
}];

