parameters.jsCode:
const geminiOutput = $input.first().json;

const articles =
  $('Rankear Evidencia Final').first().json.articles ||
  $('Build AI Evidence Context').first().json.ai_evidence_context ||
  $('Filtrar Artículos Relevantes').first().json.articles ||
  [];

const original = $('Normalizar Claim').first().json;

const lang = original.language || 'es';
const isEn = lang === 'en';

const labels = isEn
  ? {
      claimUnavailable: 'Claim unavailable',
      analyzedClaim: 'Analyzed claim',
      shortClaim: 'Claim',
      verdict: 'Verdict',
      confidence: 'Confidence',
      consensus: 'Scientific consensus',
      shortConsensus: 'Consensus',
      summary: 'Summary',
      detailedAnalysis: 'Detailed analysis',
      shortAnalysis: 'Brief analysis',
      strengths: 'Methodological strengths',
      limitations: 'Limitations',
      keyLimitations: 'Key limitations',
      biases: 'Potential biases / conflicts',
      keyCitations: 'Key citations',
      pubmedReferences: 'PubMed references',
      mainReferences: 'Main references',
      disclaimer: 'AI-generated analysis based on PubMed-indexed articles. It does not replace professional clinical judgment.',
      fullDisclaimer: 'AI-generated analysis based on PubMed-indexed articles. It does not replace professional clinical judgment. Always verify the original sources.',
      articlesAnalyzed: 'Articles analyzed',
      date: 'Date',
      parseError: 'Gemini returned an invalid format',
      parseErrorLimit: 'The AI response could not be parsed correctly',
      processingError: 'Error processing the analysis',
      technicalError: 'A technical error occurred while analyzing the evidence.',
      notDetermined: 'Not determined',
      couldNotDetermine: 'Could not be determined',
    }
  : {
      claimUnavailable: 'Claim no disponible',
      analyzedClaim: 'Afirmación analizada',
      shortClaim: 'Afirmación',
      verdict: 'Veredicto',
      confidence: 'Confianza',
      consensus: 'Consenso científico',
      shortConsensus: 'Consenso',
      summary: 'Resumen',
      detailedAnalysis: 'Análisis detallado',
      shortAnalysis: 'Análisis breve',
      strengths: 'Fortalezas metodológicas',
      limitations: 'Limitaciones',
      keyLimitations: 'Limitaciones clave',
      biases: 'Posibles sesgos / conflictos',
      keyCitations: 'Citas clave',
      pubmedReferences: 'Referencias PubMed',
      mainReferences: 'Referencias principales',
      disclaimer: 'Análisis generado por IA a partir de artículos indexados en PubMed. No sustituye juicio clínico profesional.',
      fullDisclaimer: 'Análisis generado por IA a partir de artículos indexados en PubMed. No sustituye juicio clínico profesional. Verifica siempre las fuentes originales.',
      articlesAnalyzed: 'Artículos analizados',
      date: 'Fecha',
      parseError: 'Gemini devolvió un formato inválido',
      parseErrorLimit: 'La respuesta IA no pudo parsearse correctamente',
      processingError: 'Error al procesar el análisis',
      technicalError: 'Hubo un error técnico al analizar la evidencia.',
      notDetermined: 'No determinado',
      couldNotDetermine: 'No se pudo determinar',
    };

function displayVerdict(value) {
  const map = {
    VERDADERO: isEn ? 'TRUE' : 'VERDADERO',
    PARCIALMENTE_CIERTO: isEn ? 'PARTIAL' : 'PARCIALMENTE CIERTO',
    EXAGERADO: isEn ? 'EXAGGERATED' : 'EXAGERADO',
    FALSO: isEn ? 'FALSE' : 'FALSO',
    EVIDENCIA_INSUFICIENTE: isEn ? 'INSUFFICIENT EVIDENCE' : 'EVIDENCIA INSUFICIENTE',

    TRUE: isEn ? 'TRUE' : 'VERDADERO',
    PARTIALLY_TRUE: isEn ? 'PARTIAL' : 'PARCIALMENTE CIERTO',
    EXAGGERATED: isEn ? 'EXAGGERATED' : 'EXAGERADO',
    FALSE: isEn ? 'FALSE' : 'FALSO',
    INSUFFICIENT_EVIDENCE: isEn ? 'INSUFFICIENT EVIDENCE' : 'EVIDENCIA INSUFICIENTE',

    ERROR_ANALISIS: isEn ? 'ANALYSIS ERROR' : 'ERROR DE ANÁLISIS',
  };

  return map[value] || value || 'UNKNOWN';
}

function displayConsensus(value) {
  const map = {
    FUERTE: isEn ? 'STRONG' : 'FUERTE',
    MODERADO: isEn ? 'MODERATE' : 'MODERADO',
    DÉBIL: isEn ? 'WEAK' : 'DÉBIL',
    DEBIL: isEn ? 'WEAK' : 'DÉBIL',
    MIXTO: isEn ? 'MIXED' : 'MIXTO',
    INSUFICIENTE: isEn ? 'INSUFFICIENT' : 'INSUFICIENTE',

    STRONG: isEn ? 'STRONG' : 'FUERTE',
    MODERATE: isEn ? 'MODERATE' : 'MODERADO',
    WEAK: isEn ? 'WEAK' : 'DÉBIL',
    MIXED: isEn ? 'MIXED' : 'MIXTO',
    INSUFFICIENT: isEn ? 'INSUFFICIENT' : 'INSUFICIENTE',
    UNCLEAR: isEn ? 'UNCLEAR' : 'NO CLARO',
  };

  return map[value] || value || 'UNKNOWN';
}

let analysis = {};

try {
  const text = geminiOutput.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const clean = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);

  try {
    analysis = JSON.parse(match ? match[0] : clean);
  } catch (innerError) {
    const repaired = clean
      .replace(/,\s*}/g, '}')
      .replace(/,\s*]/g, ']')
      .replace(/\n/g, ' ')
      .trim();

    try {
      analysis = JSON.parse(repaired);
    } catch (repairError) {
      analysis = {
        veredicto: 'ERROR_ANALISIS',
        explicacion_corta: labels.parseError,
        analisis_detallado: clean.slice(0, 2000),
        fortalezas: [],
        limitaciones: [labels.parseErrorLimit],
        conflictos_potenciales: labels.notDetermined,
        citas_clave: [],
        confidence_level: 'LOW',
        consensus_level: 'UNCLEAR'
      };
    }
  }
} catch (e) {
  analysis = {
    veredicto: 'ERROR_ANALISIS',
    explicacion_corta: labels.processingError,
    analisis_detallado: labels.technicalError,
    fortalezas: [],
    limitaciones: [],
    conflictos_potenciales: labels.couldNotDetermine,
    citas_clave: [],
    confidence_level: 'LOW',
    consensus_level: 'UNCLEAR'
  };
}

// ============================================
// CONFIDENCE ENFORCEMENT — MECÁNICO, NO NEGOCIABLE
// ============================================
const input = $input.first().json;

function enforceConfidence(analysis, signals) {
  let confidence = analysis.confidence_level || 'LOW';
  const consensus = (analysis.consensus_level || '').toUpperCase();

  const realArticlesCount =
    signals.articles_considered ||
    articles.length ||
    0;

  // Regla 1: MIXED/WEAK/INSUFFICIENT → nunca HIGH
  if (['MIXED', 'MIXTO', 'WEAK', 'DÉBIL', 'DEBIL', 'INSUFFICIENT', 'INSUFICIENTE'].includes(consensus)) {
    if (confidence === 'HIGH') confidence = 'MODERATE';
  }

  // Regla 2: < 3 artículos reales → nunca HIGH, máximo MODERATE
  if (realArticlesCount < 3) {
    if (confidence === 'HIGH') confidence = 'MODERATE';
  }

  // Regla 3: 0 artículos reales → LOW
  if (realArticlesCount === 0) {
    confidence = 'LOW';
  }

  // Regla 4: COI alto presente → no permitir HIGH
  if ((signals.coi_high_risk_count || 0) > 0) {
    if (confidence === 'HIGH') confidence = 'MODERATE';
  }

  // Regla 5: Claim con "cura" o absoluto sin consenso STRONG/FUERTE
  if (signals.tiene_cura || signals.tiene_absoluto) {
    if (!['STRONG', 'FUERTE', 'VERY_STRONG'].includes(consensus)) {
      if (confidence === 'HIGH') confidence = 'MODERATE';
    }
  }

  // Regla 6: Especificidad mismatch → nunca HIGH
  if (signals.specificity_mismatch) {
    if (confidence === 'HIGH') confidence = 'MODERATE';
  }

  return { ...analysis, confidence_level: confidence };
}

const signals = {
  articles_considered:
    input.evidence_consensus?.articles_considered ||
    articles.length ||
    0,
  coi_high_risk_count: input.conflict_of_interest_summary?.high_risk_count || 0,
  tiene_cura: input.tiene_cura || false,
  tiene_absoluto: input.tiene_absoluto || false,
  specificity_mismatch: input.claim_specificity?.specificity_mismatch || false,
};

analysis = enforceConfidence(analysis, signals);

// ============================================
// CALIBRACIÓN HARD-CODEADA DE CONFIDENCE Y CONSENSUS
// ============================================

// --- Extraer señales del pipeline ---
let pipelineSignals = {};
try {
  const pipelineMeta = $('Build Pipeline Meta').first().json || {};
  const consensusEvidencia = $('Construir Consenso Evidencia').first().json || {};
  const prepararBody = $('Preparar Body Gemini').first().json || {};

  pipelineSignals = {
    has_institutional_consensus: pipelineMeta.has_institutional_consensus || false,
    institutional_consensus_strength: pipelineMeta.institutional_consensus_strength || null,
    evidence_consensus_level: consensusEvidencia.evidence_consensus?.consensus_level || '',
    weighted_consensus_level: prepararBody.weighted_consensus_level || '',
    coi_high_risk_count: prepararBody.conflict_of_interest_summary?.high_risk_count || 0,
    specificity_mismatch: prepararBody.claim_specificity?.specificity_mismatch || false,
    tiene_absoluto: prepararBody.tiene_absoluto || false,
    tiene_cura: prepararBody.tiene_cura || false
  };
} catch (e) {
  pipelineSignals = {
    has_institutional_consensus: false,
    institutional_consensus_strength: null,
    evidence_consensus_level: '',
    weighted_consensus_level: '',
    coi_high_risk_count: 0,
    specificity_mismatch: false,
    tiene_absoluto: false,
    tiene_cura: false
  };
}

// --- Función calibrateConfidence ---
function calibrateConfidence(analysis, signals) {
  const {
    weighted_consensus_level,
    evidence_consensus_level,
    has_institutional_consensus,
    institutional_consensus_strength,
    coi_high_risk_count,
    specificity_mismatch,
    tiene_absoluto,
    tiene_cura
  } = signals;

  let calibratedConfidence = analysis.confidence_level || 'LOW';
  let calibrationReasons = [];

  const consensus = (evidence_consensus_level || weighted_consensus_level || '').toUpperCase();
  const verdict = (analysis.veredicto || '').toUpperCase();
  const currentConfidence = (calibratedConfidence || '').toUpperCase();

  // REGLA 1: Consenso MIXED/WEAK/INSUFFICIENT → nunca HIGH
  if (['MIXED', 'MIXTO', 'WEAK', 'DÉBIL', 'DEBIL', 'INSUFFICIENT', 'INSUFICIENTE'].includes(consensus)) {
    if (currentConfidence === 'HIGH') {
      calibratedConfidence = 'MODERATE';
      calibrationReasons.push(`Consenso pipeline es ${consensus} → confidence no puede ser HIGH`);
    }
  }

  // REGLA 2: Consenso INSUFFICIENT → máximo LOW
  if (['INSUFFICIENT', 'INSUFICIENTE'].includes(consensus)) {
    if (currentConfidence !== 'LOW') {
      calibratedConfidence = 'LOW';
      calibrationReasons.push('Consenso INSUFFICIENT → confidence = LOW');
    }
  }

  // REGLA 3: Lenguaje absoluto + veredicto parcial → no HIGH
  if ((tiene_absoluto || tiene_cura) && 
      ['EXAGERADO', 'EXAGGERATED', 'PARCIALMENTE_CIERTO', 'PARTIALLY_TRUE'].includes(verdict)) {
    if (currentConfidence === 'HIGH') {
      calibratedConfidence = 'MODERATE';
      calibrationReasons.push(`Claim con lenguaje absoluto y veredicto ${verdict} → confidence no puede ser HIGH`);
    }
  }

  // REGLA 4: Specificity mismatch sin hard outcomes → reducir
  if (specificity_mismatch && ['HIGH', 'MODERATE'].includes(currentConfidence)) {
    const hasHardOutcomes = articles.some(a => a.has_hard_outcomes || (a.hard_outcomes && a.hard_outcomes.length > 0));
    if (!hasHardOutcomes) {
      calibratedConfidence = currentConfidence === 'HIGH' ? 'MODERATE' : 'LOW';
      calibrationReasons.push(`Specificity mismatch sin hard outcomes → confidence reducida a ${calibratedConfidence}`);
    }
  }

  // REGLA 5: Alto COI → reducir UN nivel
  if ((coi_high_risk_count || 0) > 0) {
    if (currentConfidence === 'HIGH') {
      calibratedConfidence = 'MODERATE';
      calibrationReasons.push(`COI high risk (${coi_high_risk_count}) → confidence HIGH→MODERATE`);
    } else if (currentConfidence === 'MODERATE') {
      calibratedConfidence = 'LOW';
      calibrationReasons.push(`COI high risk (${coi_high_risk_count}) → confidence MODERATE→LOW`);
    }
  }

  // REGLA 6: Consenso institucional contradice claim → HIGH para rechazar
  if (has_institutional_consensus && ['VERY_STRONG', 'STRONG'].includes(institutional_consensus_strength)) {
    if (['FALSO', 'FALSE', 'EXAGERADO', 'EXAGGERATED'].includes(verdict)) {
      if (!(tiene_absoluto || tiene_cura)) {
        calibratedConfidence = 'HIGH';
        calibrationReasons.push(`Consenso institucional ${institutional_consensus_strength} contradice claim → confidence HIGH`);
      }
    }
  }

  return {
    confidence: calibratedConfidence,
    reasons: calibrationReasons,
    wasModified: calibratedConfidence !== (analysis.confidence_level || 'LOW')
  };
}

// --- Función calibrateConsensus ---
function calibrateConsensus(analysis, signals) {
  const {
    weighted_consensus_level,
    evidence_consensus_level,
    has_institutional_consensus,
    institutional_consensus_strength
  } = signals;

  let calibratedConsensus = analysis.consensus_level || 'UNCLEAR';
  let calibrationReasons = [];

  const consensus = (evidence_consensus_level || weighted_consensus_level || '').toUpperCase();
  const currentConsensus = (calibratedConsensus || '').toUpperCase();
  const verdict = (analysis.veredicto || '').toUpperCase();

  console.log({
    claim: input.claim,
    weighted_consensus_level,
    evidence_consensus_level,
    original_consensus: analysis.consensus_level,
    calibratedConsensus
  });

  // REGLA 1: Consenso institucional STRONG + claim rechazado → STRONG
  if (has_institutional_consensus && ['VERY_STRONG', 'STRONG'].includes(institutional_consensus_strength)) {
    if (['FALSO', 'FALSE', 'EXAGERADO', 'EXAGGERATED'].includes(verdict)) {
      calibratedConsensus = 'STRONG';
      calibrationReasons.push(`Consenso institucional ${institutional_consensus_strength} → consensus = STRONG`);
    }
  }

  // REGLA 2: Evidence consensus MIXED → no permitir STRONG
  if (['MIXED', 'MIXTO'].includes(consensus) && ['STRONG', 'FUERTE'].includes(currentConsensus)) {
    calibratedConsensus = 'MIXED';
    calibrationReasons.push('Evidence consensus es MIXED → consensus no puede ser STRONG');
  }

  // REGLA 3: Weighted consensus WEAK → no permitir MIXED/STRONG
  if (['WEAK', 'DÉBIL', 'DEBIL'].includes(consensus) && 
      ['MIXED', 'MIXTO', 'STRONG', 'FUERTE'].includes(currentConsensus)) {
    calibratedConsensus = 'WEAK';
    calibrationReasons.push('Weighted consensus es WEAK → consensus = WEAK');
  }

  return {
    consensus: calibratedConsensus,
    reasons: calibrationReasons,
    wasModified: calibratedConsensus !== (analysis.consensus_level || 'UNCLEAR')
  };
}

// --- Aplicar calibración ---
const confidenceCalibration = calibrateConfidence(analysis, pipelineSignals);
const consensusCalibration = calibrateConsensus(analysis, pipelineSignals);

const originalConfidence = analysis.confidence_level;
const originalConsensus = analysis.consensus_level;

analysis.confidence_level = confidenceCalibration.confidence;
analysis.consensus_level = consensusCalibration.consensus;

// Metadatos para trazabilidad
analysis._calibration = {
  confidence: {
    original: originalConfidence,
    calibrated: confidenceCalibration.confidence,
    wasModified: confidenceCalibration.wasModified,
    reasons: confidenceCalibration.reasons
  },
  consensus: {
    original: originalConsensus,
    calibrated: consensusCalibration.consensus,
    wasModified: consensusCalibration.wasModified,
    reasons: consensusCalibration.reasons
  }
};

const emoji = {
  VERDADERO: '✅',
  TRUE: '✅',

  PARCIALMENTE_CIERTO: '⚠️',
  PARTIALLY_TRUE: '⚠️',

  EXAGERADO: '⚠️',
  EXAGGERATED: '⚠️',

  FALSO: '❌',
  FALSE: '❌',

  EVIDENCIA_INSUFICIENTE: '❓',
  INSUFFICIENT_EVIDENCE: '❓',

  ERROR_ANALISIS: '⚠️'
};

const originalClaimSafe =
  original.original_claim ||
  original.claim ||
  $json.original_claim ||
  $json.claim ||
  labels.claimUnavailable;

const verdictLabel = displayVerdict(analysis.veredicto);
const consensusLabel = displayConsensus(analysis.consensus_level);

// ============================================
// WHATSAPP — bilingual ES/EN
// ============================================

let mensaje = `${emoji[analysis.veredicto] || '🔍'} *EVIDENCE CHECK*\n`;
mensaje += `━━━━━━━━━━━━━━━━━━━━\n\n`;
mensaje += `📌 *${labels.analyzedClaim}:*\n${originalClaimSafe}\n\n`;
mensaje += `🎯 *${labels.verdict}:* ${verdictLabel}\n`;
mensaje += `📊 *${labels.confidence}:* ${analysis.confidence_level || 'UNKNOWN'}\n`;
mensaje += `🧠 *${labels.consensus}:* ${consensusLabel}\n\n`;
mensaje += `📝 *${labels.summary}:* ${analysis.explicacion_corta || ''}\n\n`;
mensaje += `📊 *${labels.detailedAnalysis}:*\n${analysis.analisis_detallado || ''}\n\n`;

if (analysis.fortalezas?.length) {
  mensaje += `✅ *${labels.strengths}:*\n`;
  analysis.fortalezas.forEach(f => mensaje += `• ${f}\n`);
  mensaje += `\n`;
}

if (analysis.limitaciones?.length) {
  mensaje += `⚠️ *${labels.limitations}:*\n`;
  analysis.limitaciones.forEach(l => mensaje += `• ${l}\n`);
  mensaje += `\n`;
}

mensaje += `🔍 *${labels.biases}:*\n${analysis.conflictos_potenciales || labels.notDetermined}\n\n`;
mensaje += `📚 *${labels.pubmedReferences}:*\n`;

articles.slice(0, 5).forEach((article, idx) => {
  mensaje += `${idx + 1}. ${article.title}\n`;
  mensaje += `${article.journal} (${article.pubdate}) | PMID: ${article.pmid}\n`;
  mensaje += `${article.url}\n\n`;
});

mensaje += `⚠️ *${labels.disclaimer.split('.')[0]}:*\n`;
mensaje += `${labels.disclaimer}\n\n`;
mensaje += `🔬 ${labels.articlesAnalyzed}: ${articles.length}\n`;
mensaje += `📅 ${labels.date}: ${new Date().toISOString().split('T')[0]}`;

// ============================================
// EMAIL — bilingual ES/EN
// ============================================

const emailHtml = `
<h2>EvidenceCheck AI</h2>

<h3>${labels.analyzedClaim}</h3>
<p>${originalClaimSafe}</p>

<h3>${labels.verdict}</h3>
<p><strong>${verdictLabel}</strong></p>

<h3>${labels.confidence}</h3>
<p>${analysis.confidence_level || 'UNKNOWN'}</p>

<h3>${labels.consensus}</h3>
<p>${consensusLabel}</p>

<h3>${labels.summary}</h3>
<p>${analysis.explicacion_corta || ''}</p>

<h3>${labels.detailedAnalysis}</h3>
<p>${analysis.analisis_detallado || ''}</p>

<h3>${labels.strengths}</h3>
<ul>
${(analysis.fortalezas || []).map(f => `<li>${f}</li>`).join('')}
</ul>

<h3>${labels.limitations}</h3>
<ul>
${(analysis.limitaciones || []).map(l => `<li>${l}</li>`).join('')}
</ul>

<h3>${labels.biases}</h3>
<p>${analysis.conflictos_potenciales || labels.notDetermined}</p>

<h3>${labels.keyCitations}</h3>
<ul>
${(analysis.citas_clave || []).map(c => `<li>${c}</li>`).join('')}
</ul>

<h3>${labels.pubmedReferences}</h3>
<ol>
${articles.map(a => `
<li>
<strong>${a.title}</strong><br>
${a.authors || ''}<br>
<em>${a.journal}</em> (${a.pubdate})<br>
PMID: ${a.pmid}<br>
<a href="${a.url}">${a.url}</a>
</li>
`).join('')}
</ol>

<hr>

<p><strong>${labels.disclaimer}:</strong> ${labels.fullDisclaimer}</p>

<p><strong>${labels.date}:</strong> ${new Date().toISOString().split('T')[0]}</p>
`;

const MAX_WHATSAPP = 3900;

if (mensaje.length > MAX_WHATSAPP) {
  const refs = articles.slice(0, 3).map((article, idx) =>
    `${idx + 1}. ${article.title}\nPMID: ${article.pmid}\n${article.url}`
  ).join('\n\n');

  mensaje = `${emoji[analysis.veredicto] || '🔍'} *EVIDENCE CHECK*\n`;
  mensaje += `━━━━━━━━━━━━━━━━━━━━\n\n`;
  mensaje += `📌 *${labels.shortClaim}:*\n${originalClaimSafe}\n\n`;
  mensaje += `🎯 *${labels.verdict}:* ${verdictLabel}\n`;
  mensaje += `📊 *${labels.confidence}:* ${analysis.confidence_level || 'UNKNOWN'}\n`;
  mensaje += `🧠 *${labels.shortConsensus}:* ${consensusLabel}\n\n`;
  mensaje += `📝 *${labels.summary}:* ${analysis.explicacion_corta || ''}\n\n`;
  mensaje += `📊 *${labels.shortAnalysis}:*\n${String(analysis.analisis_detallado || '').slice(0, 1200)}...\n\n`;

  if (analysis.limitaciones?.length) {
    mensaje += `⚠️ *${labels.keyLimitations}:*\n`;
    analysis.limitaciones.slice(0, 3).forEach(l => mensaje += `• ${l}\n`);
    mensaje += `\n`;
  }

  mensaje += `📚 *${labels.mainReferences}:*\n${refs}\n\n`;
  mensaje += `⚠️ ${labels.disclaimer}\n`;
  mensaje += `🔬 ${labels.articlesAnalyzed}: ${articles.length}`;
}

if (
  analysis.consensus_level === 'MIXED' &&
  analysis.evidence_consensus_assessment?.overall_consensus === 'WEAK'
) {
  analysis.evidence_consensus_assessment.overall_consensus = 'MIXED';
}

if (
  analysis.consensus_level === 'STRONG' &&
  analysis.evidence_consensus_assessment?.overall_consensus === 'WEAK'
) {
  analysis.evidence_consensus_assessment.overall_consensus = 'STRONG';
}

if (
  analysis.consensus_level === 'MODERATE' &&
  analysis.evidence_consensus_assessment?.overall_consensus === 'WEAK'
) {
  analysis.evidence_consensus_assessment.overall_consensus = 'MODERATE';
}

// ============================================
// VALIDAR Y LIMPIAR NÚMERO DE TELÉFONO
// ============================================

function getValidWhatsAppNumber(phone) {
  const invalidValues = ['unknown', '', null, undefined, '=', '#', 'default', 'undefined', 'null', '0', '-1'];
  const phoneStr = String(phone || '').trim();

  if (invalidValues.includes(phoneStr)) {
    return null;
  }

  const digitsOnly = phoneStr.replace(/\D/g, '');
  if (digitsOnly.length < 8) {
    return null;
  }

  return digitsOnly;
}

let whatsappNumber = getValidWhatsAppNumber(original.from);

