} else {
  if (wantsMortality) targetOutcomes.push('mortality', 'all-cause mortality', 'cardiovascular mortality', 'death');
  if (wantsCardio) targetOutcomes.push('cardiovascular disease', 'cardiovascular events', 'blood pressure', 'hypertension', 'stroke', 'myocardial infarction');
  if (wantsCancer) targetOutcomes.push('cancer', 'neoplasms', 'melanoma', 'tumor', 'carcinoma', 'skin cancer');
  if (wantsWeight) targetOutcomes.push('body weight', 'weight loss', 'obesity', 'body mass index', 'bmi', 'waist circumference');
  if (wantsDiabetes) targetOutcomes.push('glucose', 'insulin', 'insulin resistance', 'hba1c', 'diabetes');
  if (wantsTreatment || wantsSupplement) targetOutcomes.push('randomized controlled trial', 'clinical trial', 'efficacy', 'safety', 'adverse events');
}

if (targetOutcomes.length === 0) targetOutcomes = uniqueTerms;

targetOutcomes = [...new Set(targetOutcomes.map(t => String(t).toLowerCase()))];

const expandedOutcomeTerms = [];

for (const term of targetOutcomes) {
  expandedOutcomeTerms.push(term);

  const cleanTerm = String(term).toLowerCase().trim();

  if (outcomeSynonymsMap[cleanTerm]) {
