      'neoplasms',
      'neoplasm',
      'tumor',
      'tumors',
      'carcinoma',
      'incidence'
    ].includes(t)
  );
}

const conditionalPopulations = [
  { term: 'children', allowed: wantsChildren },
  { term: 'pediatric', allowed: wantsChildren },
  { term: 'adolescent', allowed: wantsChildren },
  { term: 'pregnant', allowed: wantsPregnancy },
  { term: 'pregnancy', allowed: wantsPregnancy },
  { term: 'chronic kidney disease', allowed: wantsCKD },
  { term: 'renal insufficiency', allowed: wantsCKD },
  { term: 'dialysis', allowed: wantsCKD },
  { term: 'heart failure', allowed: wantsHeartFailure },
  { term: 'animal model', allowed: false },
  { term: 'mice', allowed: false },
  { term: 'rats', allowed: false }
];

const relationTerms = [
  'associated with',
  'association',
  'associations',
  'associations between',
  'harmful associations',
  'association between',
  'associated',
  'risk of',
  'higher risk',
  'lower risk',
  'increased risk',
  'reduced risk',
  'linked to',
  'relationship between',
  'effect of',
  'impact of',
  'cause',
  'causes',
  'causal',
  'correlated with',
  'predicts',
  'predictive of'
];

const nullRelationPatterns = [
  "does not induce",
  "did not induce",
  "does not cause",
  "did not cause",
  "does not increase",
  "did not increase",
  "does not alter",
  "did not alter",
  "not associated with",
  "no association",
  "no evidence of",
  "no significant effect",
  "no significant effects",
  "no detrimental effects",
  "without effect",
  "had no effect",
