];

const scored = articles.map(article => {
  const title = String(article.title || '').toLowerCase();
  const abstract = String(article.abstract || '').toLowerCase();
  const mesh = (article.mesh_terms || []).join(' ').toLowerCase();
  const pbTypes = (article.publication_types || []).join(' ').toLowerCase();
  const fullText = `${title} ${abstract} ${mesh} ${pbTypes}`;

let underlying_evidence_type = 'UNCLEAR';

const publicationTypesText = (article.publication_types || []).join(' ').toLowerCase();
const meshText = (article.mesh_terms || []).join(' ').toLowerCase();
const abstractText = String(article.abstract || '').toLowerCase();
const titleText = String(article.title || '').toLowerCase();

const combinedText = `${titleText} ${abstractText} ${publicationTypesText}`;

// 1. Primero: meta-análisis / umbrella review de evidencia observacional
if (
  combinedText.includes('meta-analyses of prospective observational studies') ||
  combinedText.includes('meta-analysis of prospective observational studies') ||
  combinedText.includes('meta-analysis of cohort studies') ||
  combinedText.includes('meta-analysis of observational studies') ||
  combinedText.includes('systematic review and meta-analysis of cohort studies') ||
  combinedText.includes('umbrella review of meta-analyses of prospective observational studies') ||
  combinedText.includes('umbrella review of observational studies') ||
  combinedText.includes('observational studies as topic') ||
  meshText.includes('observational studies as topic')
) {
  underlying_evidence_type = 'OBSERVATIONAL_META_ANALYSIS';
}

// 2. Segundo: evidencia intervencional
else if (
  combinedText.includes('randomized controlled trial') ||
  combinedText.includes('randomised controlled trial') ||
  combinedText.includes('clinical trial') ||
  combinedText.includes('intervention trial') ||
  publicationTypesText.includes('randomized controlled trial') ||
  publicationTypesText.includes('clinical trial')
) {
  underlying_evidence_type = 'INTERVENTIONAL';
}

// 2.5 Revisiones sistemáticas observacionales sin meta-análisis claro
else if (
  combinedText.includes('systematic review') &&
  (
    combinedText.includes('association') ||
    combinedText.includes('associations exist') ||
    combinedText.includes('associated with') ||
    combinedText.includes('inverse association') ||
    combinedText.includes('risk reduction') ||
    combinedText.includes('prospective study') ||
    combinedText.includes('epic cohort') ||
    combinedText.includes('prospective investigation')
  )
) {
  underlying_evidence_type = 'OBSERVATIONAL_REVIEW';
}

// 3. Tercero: evidencia observacional primaria
else if (
  combinedText.includes('prospective observational') ||
  combinedText.includes('prospective cohort') ||
  combinedText.includes('cohort study') ||
  combinedText.includes('cohort studies') ||
  combinedText.includes('observational study') ||
  combinedText.includes('observational studies') ||
  combinedText.includes('observational evidence') ||
  combinedText.includes('case-control') ||
  combinedText.includes('cross-sectional') ||
  combinedText.includes('prospective studies') ||
  meshText.includes('cohort studies') ||
  meshText.includes('prospective studies') ||
  meshText.includes('case-control studies') ||
  meshText.includes('cross-sectional studies')
) {
  underlying_evidence_type = 'OBSERVATIONAL';
}

// 4. Último: preclínico, solo si NO parece revisión/meta-análisis humano
else if (
  (
    combinedText.includes('animal model') ||
    combinedText.includes('mouse model') ||
    combinedText.includes('mice') ||
    combinedText.includes('rats') ||
    combinedText.includes('murine') ||
    combinedText.includes('in vitro')
  )
  &&
  !combinedText.includes('meta-analysis')
  &&
  !combinedText.includes('systematic review')
  &&
  !combinedText.includes('cohort')
  &&
  !combinedText.includes('human')
  &&
  !meshText.includes('humans')
) {
  underlying_evidence_type = 'PRECLINICAL';
}

  const matched_exposure = exposureTerms.filter(term =>
  containsExactTerm(fullText, term)
);
  const matched_outcomes = [];
  const matched_terms = [];

  const canonicalClaimExposures =
  exposureTerms.map(getCanonicalExposure);

const articleExposureCanonicals =
  matched_exposure.map(getCanonicalExposure);

const canonicalExposureOverlap =
  canonicalClaimExposures.filter(exp =>
    articleExposureCanonicals.includes(exp)
  );

const hasExposure =
  canonicalExposureOverlap.length > 0;
const hasOutcome = targetOutcomes.some(term =>
  containsExactTerm(fullText, term)
);

const titleExposureMatches = exposureTerms.filter(term =>
  containsExactTerm(title, term)
);

const titleOutcomeMatches = targetOutcomes.filter(term =>
  containsExactTerm(title, term)
);;

  const titleHasExposure = titleExposureMatches.length > 0;
  const titleHasOutcome = titleOutcomeMatches.length > 0;
  const strongExposureTitleMatch = titleExposureMatches.length > 0;

  const firstAbstractPart = abstract.slice(0, 1200);

  const normalizedAbstract = firstAbstractPart
    .toLowerCase()
    .replace(/\n/g, ' ')
    .replace(/consumption/g, 'intake')
    .replace(/dietary/g, '')
    .replace(/added/g, '')
    .replace(/free/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  const titleRelationMatch =
    titleHasExposure &&
    titleHasOutcome &&
    relationTerms.some(term => title.includes(term));

  const sentences = normalizedAbstract
    .split(/(?<=[.!?])\s+/)
    .map(s => s.trim())
    .filter(Boolean);

  let debugMatches = [];

  const sentenceRelationMatch = sentences.some(sentence => {
    const hasExp = exposureTerms.some(exp => {
      const normalizedExp = exp
        .replace(/dietary/g, '')
        .replace(/added/g, '')
        .replace(/free/g, '')
        .replace(/consumption/g, 'intake')
        .trim();

      const expTokens = normalizedExp
        .split(/\s+/)
        .filter(t => t.length > 2);

      const matchedTokens = expTokens.filter(token =>
        sentence.includes(token)
      );

      return matchedTokens.length >= Math.max(1, Math.ceil(expTokens.length * 0.5));
    });

    const hasOut = targetOutcomes.some(out => {
      const normalizedOut = out
        .replace(/cancers/g, 'cancer')
        .replace(/neoplasms/g, 'cancer')
        .replace(/tumors/g, 'tumor')
        .trim();

      if (sentence.includes(normalizedOut)) return true;

      const outTokens = normalizedOut
        .split(/\s+/)
        .filter(t => t.length > 2);

      const matchedTokens = outTokens.filter(token =>
        sentence.includes(token)
      );

      return matchedTokens.length >= Math.max(1, Math.ceil(outTokens.length * 0.5));
    });

    const hasRel =
  relationTerms.some(rel =>
    sentence.includes(rel)
  ) ||
  nullRelationPatterns.some(pattern =>
    sentence.includes(pattern)
  );

    debugMatches.push({
      sentence,
      hasExp,
      hasOut,
      hasRel
    });

    return hasExp && hasOut && hasRel;
  });

  const proximityRelationMatch =
    exposureTerms.some(exp =>
      targetOutcomes.some(out => {
        const expIndex = normalizedAbstract.indexOf(
          String(exp)
            .replace(/dietary/g, '')
            .replace(/added/g, '')
            .replace(/free/g, '')
            .trim()
        );

        const outIndex = normalizedAbstract.indexOf(
          String(out)
            .replace(/neoplasms/g, 'cancer')
            .trim()
        );

        if (expIndex === -1 || outIndex === -1) return false;

        const distance = Math.abs(expIndex - outIndex);
        return distance < 160;
      })
    );

  const abstractRelationMatch =
    sentenceRelationMatch || proximityRelationMatch;

  const strongRelationMatch =
    titleRelationMatch || abstractRelationMatch;

  let relevance_score = 0;

  uniqueTerms.forEach(term => {
    if (title.includes(term)) {
      relevance_score += 20;
      matched_terms.push(term);
    } else if (mesh.includes(term)) {
      relevance_score += 10;
      matched_terms.push(term);
    } else if (abstract.includes(term)) {
      relevance_score += 2;
      matched_terms.push(term);
    }
  });

  targetOutcomes.forEach(outcome => {
    if (title.includes(outcome)) {
      relevance_score += 18;
      matched_outcomes.push(outcome);
    } else if (mesh.includes(outcome)) {
      relevance_score += 10;
      matched_outcomes.push(outcome);
    } else if (abstract.includes(outcome)) {
      relevance_score += 3;
      matched_outcomes.push(outcome);
    }
  });

  if (titleHasExposure) relevance_score += 18;
  if (titleHasOutcome) relevance_score += 12;
  if (titleHasExposure && titleHasOutcome) relevance_score += 25;

  if (strongExposureTitleMatch) relevance_score += 35;

  relevance_score += Math.min(article.evidence_weight || 0, 18);

  if (article.is_human_evidence) relevance_score += 4;

  if (article.has_hard_outcomes) {
    relevance_score += wantsMortality || wantsCardio || wantsCancer ? 8 : 4;
  }

  if (article.has_surrogate_outcomes) {
    relevance_score += wantsCardio || wantsDiabetes || wantsWeight ? 3 : 0;
  }

  const design = String(article.study_design || '').toUpperCase();

  if (design.includes('SYSTEMATIC_REVIEW_META_ANALYSIS')) relevance_score += 10;
  else if (design.includes('META_ANALYSIS')) relevance_score += 9;
  else if (design.includes('SYSTEMATIC_REVIEW')) relevance_score += 8;
  else if (design.includes('RCT')) relevance_score += wantsTreatment || wantsSupplement ? 10 : 6;
  else if (design.includes('COHORT')) relevance_score += wantsMortality || wantsCancer ? 6 : 3;

  conditionalPopulations.forEach(p => {
    if (!p.allowed && fullText.includes(p.term)) relevance_score -= 10;
  });

  const indirectTopics = [
    'gut microbiota',
    'ultra-processed',
    'fatty liver',
    'metabolomics',
    'genetic polymorphism',
    'in vitro'
  ];

  indirectTopics.forEach(term => {
    if (!claimText.includes(term) && fullText.includes(term)) relevance_score -= 8;
  });

  if (matched_terms.length === 0 && matched_outcomes.length === 0) {
    relevance_score -= 15;
  }

  if (hasExposure && hasOutcome) {
    relevance_score += 25;
  } else if (hasExposure && !hasOutcome) {
    relevance_score -= 28;
  } else if (!hasExposure && hasOutcome) {
    relevance_score -= 60;
  } else {
    relevance_score -= 30;
  }

  if (hasExposure && !titleHasExposure) relevance_score -= 20;
  if (hasOutcome && !titleHasOutcome) relevance_score -= 10;

  if (hasExposure && hasOutcome && !strongExposureTitleMatch) {
    relevance_score -= 35;
  }

  if (strongRelationMatch) {
    relevance_score += 35;
  }

  if (hasExposure && hasOutcome && !strongRelationMatch) {
    relevance_score -= 20;
  }

  if (!hasExposure && hasOutcome) {
    relevance_score -= 30;
  }

relevance_score = Math.max(0, Math.min(100, relevance_score));

article.canonical = article.canonical || {};

article.canonical.relevance = {
  score: relevance_score,
  has_exposure: hasExposure,
  has_outcome: hasOutcome,
  strong_relation_match: strongRelationMatch
};

  return {
    ...article,
    relevance_score,
    matched_terms: [...new Set(matched_terms)],
    matched_outcomes: [...new Set(matched_outcomes)],
    matched_exposure: [...new Set(matched_exposure)],
    canonical_exposure_overlap: canonicalExposureOverlap,
    title_exposure_matches: [...new Set(titleExposureMatches)],
    title_outcome_matches: [...new Set(titleOutcomeMatches)],
    has_exposure: hasExposure,
    has_outcome: hasOutcome,
    title_has_exposure: titleHasExposure,
    title_has_outcome: titleHasOutcome,
    strong_exposure_title_match: strongExposureTitleMatch,
    title_relation_match: titleRelationMatch,
    abstract_relation_match: abstractRelationMatch,
    sentence_relation_match: sentenceRelationMatch,
    strong_relation_match: strongRelationMatch,
    debug_sentence_matches: debugMatches,
    underlying_evidence_type,
causal_inference_strength:
  underlying_evidence_type === 'INTERVENTIONAL'
    ? 'MODERATE_TO_HIGH'
