    ? 'LOW_TO_MODERATE'
    : underlying_evidence_type === 'OBSERVATIONAL_REVIEW'
    ? 'LOW_TO_MODERATE'
    : underlying_evidence_type === 'OBSERVATIONAL'
    ? 'LOW'
    : underlying_evidence_type === 'PRECLINICAL'
    ? 'VERY_LOW'
    : 'UNCLEAR'
  };
});

console.log('scored length (después de mapear):', scored ? scored.length : 'scored no definido');

const sortedScored = scored
  .sort((a, b) => b.relevance_score - a.relevance_score);

const SEMANTIC_THRESHOLD = 20;

const filtered = sortedScored
  .filter(a =>
    a.has_exposure === true &&
    a.has_outcome === true &&
    a.strong_relation_match === true &&
    a.semantic_claim_match_score >= SEMANTIC_THRESHOLD
  )
  .slice(0, 12);

const selectedArticles = filtered;

const coverageArticles =
  selectedArticles.length >= 3
    ? selectedArticles
    : sortedScored
        .filter(a =>
          a.has_exposure === true &&
          a.has_outcome === true &&
          Number(a.semantic_claim_match_score || 0) >= 40 &&
          Number(a.relevance_score || 0) >= 40
        )
        .slice(0, 12);

const strongMatchCount = coverageArticles.filter(a => a.strong_relation_match).length;
const exposureMatchCount = coverageArticles.filter(a => a.has_exposure).length;
const outcomeMatchCount = coverageArticles.filter(a => a.has_outcome).length;

const avgRelevanceScore = coverageArticles.length
  ? coverageArticles.reduce((sum, a) => sum + Number(a.relevance_score || 0), 0) / coverageArticles.length
  : 0;

let coverageQuality = 'INSUFFICIENT';

if (strongMatchCount >= 2 && avgRelevanceScore >= 80) {
  coverageQuality = 'HIGH';
} else if (strongMatchCount >= 1 && avgRelevanceScore >= 40) {
  coverageQuality = 'MODERATE';
} else if (exposureMatchCount > 0 && outcomeMatchCount > 0) {
  coverageQuality = 'LOW';
}

const directlyRelevantArticles = coverageArticles.filter(a => {
  const hasScore = a.final_score != null && Number(a.final_score) > 0;
  const hasExposure = a.has_exposure === true;
  const hasOutcome = a.has_outcome === true;
  const semanticOK = Number(a.semantic_claim_match_score || 0) >= 40;
  const relevanceOK = Number(a.relevance_score || 0) >= 50;

  const highSemanticMatch = Number(a.semantic_claim_match_score || 0) >= 80;

  const directRelationOK = highSemanticMatch ||
    a.strong_relation_match === true ||
    a.title_relation_match === true ||
    a.abstract_relation_match === true ||
    a.sentence_relation_match === true;

  const exposureContextPenalty = Number(a.relevance_debug?.exposure_context_penalty || 0);
  const noExposureContextPenalty = exposureContextPenalty === 0;

  return (
    hasScore &&
    hasExposure &&
    hasOutcome &&
    semanticOK &&
    relevanceOK &&
    directRelationOK &&
    noExposureContextPenalty
  );
});

