// ============================================
// CONSTRUIR CONSENSO EVIDENCIA — VERSIÓN CORREGIDA v1.1
// Distingue entre:
//   A) Consenso real de apoyo/contradicción
//   B) Unanimidad de UNCLEAR = artículos no relevantes
//   C) DOES_NOT_SUPPORT = evidencia neutra/no apoyo, no contradicción
//   D) Evidencia insuficiente
//   E) Apoyo fuerte con artículos de alta calidad
// ============================================

const input = $input.first().json;
const articles = input.articles || [];

// ============================================
// FUNCIÓN AUXILIAR: Detectar null-result studies
// Un null-result study tiene lenguaje de "no efecto", "no asociación",
// "no significativo" en el contexto del claim, NO solo "no encontramos nada"
// ============================================

function isNullResultStudy(article) {
  const text = String(article.abstract || article.title || '').toLowerCase();

  // Patrones de null-result fuertes
  const nullPatterns = [
    /no significant (?:difference|effect|association|correlation)/i,
    /did not (?:find|show|demonstrate|support)/i,
    /no (?:evidence|support|effect|association|correlation|relationship)/i,
    /not associated with/i,
    /null (?:effect|result|finding)/i,
    /non-significant/i,
    /p\s*>\s*0\.05/i,
    /confidence interval includes (?:null|zero|1\.0|1)/i,
    /no statistically significant/i,
    /failed to (?:find|show|demonstrate)/i,
    /absence of (?:effect|association|relationship)/i
  ];

  const hasNullLanguage = nullPatterns.some(p => p.test(text));

  // Adicional: verificar que el estudio realmente investigó el claim
  // (no es un estudio tangencial que menciona "no encontramos nada" sobre otro tema)
  const hasExposure = article.has_exposure || article.canonical?.relevance?.has_exposure;
  const hasOutcome = article.has_outcome || article.canonical?.relevance?.has_outcome;
  const isRelevant = hasExposure && hasOutcome;

  return hasNullLanguage && isRelevant;
}

// ============================================
// FUNCIÓN AUXILIAR: Detectar evidencia de contradicción real
// Contradicción = efecto en dirección opuesta al claim
// ============================================

function hasRealContradiction(article, claimDirection) {
  const relation = article.relation_to_claim || 
                   article.canonical?.directionality?.relation || 
                   'UNCLEAR';

  if (relation === 'CONTRADICTS_CLAIM') return true;

  // Si el claim dice "beneficial" y el estudio muestra daño
  const evidenceDir = article.evidence_direction || 
                      article.canonical?.directionality?.evidence_direction;

  if (claimDirection === 'beneficial' && 
      evidenceDir === 'HARMFUL_OR_INCREASED_RISK') {
    return true;
  }

  if (claimDirection === 'harmful' && 
      evidenceDir === 'BENEFICIAL_OR_PROTECTIVE') {
    return true;
  }

  return false;
}

// ============================================
// FUNCIÓN PRINCIPAL DE CONSENSO — VERSIÓN CORREGIDA
// ============================================

function calcConsensusLevel(
  supporting,
  contradicting,
  neutral,
  unclear,
  supportsPartialBenefit,
  total,
  insufficientRelevance,
  hasStrongSupport,
  hasMixedEvidence,
  nullResultCount,
  relevantArticleCount
) {
  if (total === 0) {
    return {
      consensus_level: 'INSUFFICIENT',
      consensus_note: 'No hay artículos para evaluar.',
      gemini_instruction:
        'No articles available. Respond with EVIDENCIA_INSUFICIENTE and explain no relevant evidence was found.'
    };
  }

  if (insufficientRelevance) {
    return {
      consensus_level: 'INSUFFICIENT',
      consensus_note:
        'Los artículos recuperados no son directamente relevantes para evaluar el claim. La query de búsqueda puede haber sido subóptima.',
      gemini_instruction:
        'CRITICAL: The retrieved articles do not directly address this specific claim. You MUST respond with EVIDENCIA_INSUFICIENTE. Explain clearly that the available evidence does not allow evaluation of this claim, and that the search may have returned tangentially related articles. Do NOT invent a verdict based on indirect evidence.'
    };
  }

if (supportsPartialBenefit > 0) {

  return {

    consensus_level: 'MIXED',

    consensus_note:
      `${supportsPartialBenefit} estudios muestran beneficios parciales pero no respaldan completamente el claim.`,

    gemini_instruction:
      'Evidence supports partial benefits but not the full claim. Consensus is MIXED. For absolute claims such as cure, eliminate, reverse completely, or fully prevent, the verdict should generally be EXAGERADO with MODERATE confidence.'

  };

}

  const unclearRatio = unclear / total;
  const supportRatio = supporting / total;
  const contradictRatio = contradicting / total;
  const neutralRatio = neutral / total;
  const nullResultRatio = relevantArticleCount > 0 ? nullResultCount / relevantArticleCount : 0;

  console.log('=== CONSENSO DEBUG ===');
  console.log('supporting:', supporting, 'contradicting:', contradicting, 'neutral:', neutral, 'unclear:', unclear);
  console.log('nullResultCount:', nullResultCount, 'relevantArticleCount:', relevantArticleCount);
  console.log('nullResultRatio:', nullResultRatio);
  console.log('hasMixedEvidence:', hasMixedEvidence);

  // Casi todo UNCLEAR puro = ausencia de evidencia directa.
  if (
    unclearRatio >= 0.8 &&
    neutral === 0 &&
    !hasMixedEvidence
  ) {
    return {
      consensus_level: 'INSUFFICIENT',
      consensus_note: `El ${Math.round(unclearRatio * 100)}% de los artículos no tiene dirección clara respecto al claim. Esto indica falta de evidencia aplicable, NO consenso.`,
      gemini_instruction:
        'Most articles have UNCLEAR relation to this specific claim. This means the evidence base is insufficient to evaluate it — it does NOT mean the claim is false. Respond with EVIDENCIA_INSUFICIENTE and explain the distinction between "no evidence found" and "evidence contradicts the claim".'
    };
  }

  // ============================================
  // CORRECCIÓN PRINCIPAL: MIXED vs MODERATE
  // ============================================

  // CASO 1: Apoyo + null-results con evidencia real de no-efecto
  // Esto es MIXED, no MODERATE
  if (
    supporting > 0 &&
    contradicting === 0 &&
    neutral > 0 &&
    nullResultCount > 0 &&
    nullResultRatio >= 0.3  // Al menos 30% de los artículos relevantes son null-results
  ) {
    const balance = Math.abs(supporting - nullResultCount);

    if (balance <= 1) {
      return {
        consensus_level: 'MIXED',
        consensus_note: `Evidencia mixta: ${supporting} estudios muestran efecto, ${nullResultCount} estudios con resultados nulos (no efecto significativo). No hay consenso claro en la literatura.`,
        gemini_instruction: 'CRITICAL: The evidence is MIXED. There are studies showing an effect AND studies showing no significant effect (null results). This is NOT "moderate consensus" — it represents genuine scientific disagreement or context-dependency. You MUST use consensus_level MIXED. The verdict should reflect this uncertainty: PARCIALMENTE_CIERTO with MODERATE confidence, or EXAGERADO if the claim overstates the certainty.'
      };
    } else if (supporting > nullResultCount) {
      return {
        consensus_level: 'MIXED',
        consensus_note: `Mayoría de apoyo (${supporting} vs ${nullResultCount} null-results), pero la presencia de estudios nulos significativos indica que el efecto no es universal o depende del contexto.`,
        gemini_instruction: 'The evidence leans toward supporting the claim, but null-result studies exist. This indicates the effect is likely real but context-dependent, inconsistent across populations, or small in magnitude. Use MIXED consensus with careful explanation of the nuance.'
      };
    } else {
      return {
        consensus_level: 'MIXED',
        consensus_note: `Mayoría de null-results (${nullResultCount} vs ${supporting} de apoyo). El efecto, si existe, es inconsistente o depende fuertemente del contexto.`,
        gemini_instruction: 'Most studies do not find a significant effect. Use MIXED consensus and consider whether the claim is EXAGERADO or PARCIALMENTE_CIERTO with very careful caveats. Confidence should likely be LOW or MODERATE.'
      };
    }
  }

  // CASO 2: Apoyo + neutral SIN null-results claros
  // Estos "neutral" probablemente son estudios de baja calidad o tangenciales
  // → MODERATE es correcto aquí
  if (
    supporting > 0 &&
    contradicting === 0 &&
    neutral > 0 &&
    nullResultCount === 0
  ) {
    return {
      consensus_level: 'MODERATE',
      consensus_note:
        'Existe apoyo al claim y parte de la evidencia no muestra un efecto claro, pero no hay contradicción directa ni null-results de alta calidad.',
      gemini_instruction: ''
    };
  }

  // Evidencia mixta real: apoyo y contradicción directa.
  if (supporting > 0 && contradicting > 0) {
    const balance = Math.abs(supportRatio - contradictRatio);

    if (balance < 0.25) {
      return {
        consensus_level: 'MIXED',
        consensus_note:
          'Evidencia dividida de forma aproximadamente igual entre apoyo y contradicción directa.',
        gemini_instruction: ''
      };
    }

    if (supportRatio > contradictRatio) {
      return {
        consensus_level: 'WEAK',
        consensus_note:
          'Tendencia de apoyo al claim, pero con contradicciones directas significativas.',
        gemini_instruction: ''
      };
    }

    return {
      consensus_level: 'WEAK',
      consensus_note:
        'Tendencia contradictoria al claim, pero con algunos apoyos.',
      gemini_instruction: ''
    };
  }

  // Solo apoyo, sin contradicciones ni evidencia neutra relevante.
  if (supporting > 0 && contradicting === 0) {
    if (hasStrongSupport && supporting >= 2) {
      return {
        consensus_level: 'STRONG',
        consensus_note:
          'Existe apoyo consistente y al menos un artículo de alta calidad con fuerte relación al claim.',
        gemini_instruction: ''
      };
    }

    if (supportRatio >= 0.7 && supporting >= 3) {
      return {
        consensus_level: 'STRONG',
        consensus_note: `${supporting} de ${total} artículos apoyan el claim sin contradicciones.`,
        gemini_instruction: ''
      };
    }

    if (supportRatio >= 0.5 || supporting >= 2) {
      return {
        consensus_level: 'MODERATE',
        consensus_note:
          'Apoyo moderado al claim, sin contradicciones directas.',
        gemini_instruction: ''
      };
    }

    return {
      consensus_level: 'WEAK',
      consensus_note:
        'Apoyo débil al claim, basado en pocos artículos relevantes.',
      gemini_instruction: ''
    };
  }

  // Solo contradicciones directas, sin apoyo.
  if (contradicting > 0 && supporting === 0) {
    if (contradictRatio >= 0.7 && contradicting >= 3) {
      return {
        consensus_level: 'STRONG',
        consensus_note: `${contradicting} de ${total} artículos contradicen directamente el claim.`,
        gemini_instruction: ''
      };
    }

    return {
      consensus_level: 'MODERATE',
      consensus_note:
        'Contradicción moderada al claim.',
      gemini_instruction: ''
    };
  }

  // Solo evidencia neutra/no apoyo.
  if (neutral > 0 && supporting === 0 && contradicting === 0) {
    if (neutralRatio >= 0.7 && neutral >= 2) {
      return {
        consensus_level: 'MODERATE',
        consensus_note:
          'La mayoría de la evidencia relevante no apoya el claim, aunque no lo contradice directamente.',
        gemini_instruction: ''
      };
    }

    return {
      consensus_level: 'WEAK',
      consensus_note:
        'Hay evidencia limitada que no apoya claramente el claim.',
      gemini_instruction: ''
    };
  }

  return {
    consensus_level: 'INSUFFICIENT',
    consensus_note:
      'No hay evidencia directa suficiente para determinar consenso.',
    gemini_instruction:
      'Evidence is insufficient to evaluate this claim. Respond with EVIDENCIA_INSUFICIENTE.'
  };
