             /(cancer|melanoma|carcinoma|piel|skin).*(sun|uv|solar|ultraviolet|bronce|tanning|sol)/i.test(claim),
    institutions: ['IARC', 'WHO', 'CDC'],
    consensus_statement: 'UV radiation is a Group 1 IARC carcinogen. Established causal relationship with skin cancer (melanoma, BCC, SCC). Tanning increases cumulative UV dose and skin cancer risk. Photoadaptation does NOT eliminate carcinogenic risk.',
    consensus_level: 'VERY_STRONG',
    claim_direction: 'harmful',
    typical_claim_direction: 'beneficial'
  },
  tobacco_cancer: {
    matches: /(tobacco|smoking|cigarette|tabaco|fumar|cigarro).*(cancer|lung|pulmon|health|salud)/i.test(claim) ||
             /(cancer).*(tobacco|smoking|cigarette|tabaco)/i.test(claim),
    institutions: ['IARC', 'WHO', 'CDC'],
    consensus_statement: 'Tobacco smoking is a Group 1 IARC carcinogen. Established causal relationship with lung cancer and multiple other cancers.',
    consensus_level: 'VERY_STRONG',
    claim_direction: 'harmful',
    typical_claim_direction: 'harmful'
  },
  asbestos: {
    matches: /(asbestos|asbesto|amianto)/i.test(claim),
    institutions: ['IARC', 'WHO'],
    consensus_statement: 'Asbestos is a Group 1 IARC carcinogen. Established causal relationship with mesothelioma and lung cancer.',
    consensus_level: 'VERY_STRONG',
    claim_direction: 'harmful',
    typical_claim_direction: 'harmful'
  },
  alcohol_cancer: {
    matches: /(alcohol).*(cancer|tumor|salud|health)/i.test(claim),
    institutions: ['IARC', 'WHO'],
    consensus_statement: 'Alcohol is a Group 1 IARC carcinogen. Established causal relationship with multiple cancers including breast, colorectal, liver.',
    consensus_level: 'STRONG',
    claim_direction: 'harmful',
    typical_claim_direction: 'harmful'
  },
  processed_meat: {
    matches: /(processed meat|carne procesada|embutido|salchicha|bacon).*(cancer|colorectal)/i.test(claim),
    institutions: ['IARC', 'WHO'],
    consensus_statement: 'Processed meat is a Group 1 IARC carcinogen for colorectal cancer.',
    consensus_level: 'STRONG',
    claim_direction: 'harmful',
    typical_claim_direction: 'harmful'
  },
  sugar_cancer: {
    matches:
  /(sugar|azucar|glucose|fructose).*(cancer|tumor)/i.test(claim) ||
  /(cancer|tumor).*(sugar|azucar|glucose|fructose)/i.test(claim),
    institutions: [],
    consensus_statement: 'No established direct causal relationship between sugar and cancer per IARC/WHO. Indirect pathway via obesity exists. Direct causation claims are NOT supported by institutional consensus.',
    consensus_level: 'WEAK',
    claim_direction: 'neutral',
    typical_claim_direction: 'harmful'
  },
  vaccine_safety: {
    matches: /(vaccine|vacuna).*(safe|segura|dangerous|peligrosa|autism|autismo|daño|harm)/i.test(claim),
    institutions: ['WHO', 'CDC', 'EMA'],
    consensus_statement: 'Approved vaccines have established safety profiles per WHO/CDC/EMA. No causal link between vaccines and autism.',
    consensus_level: 'VERY_STRONG',
    claim_direction: 'safe',
    typical_claim_direction: 'safe'
  },
  air_pollution: {
    matches: /(air pollution|contaminacion|polución|pm2|pm10|particulas).*(health|salud|cancer|lung|pulmon)/i.test(claim),
    institutions: ['IARC', 'WHO'],
    consensus_statement: 'Outdoor air pollution is a Group 1 IARC carcinogen. Established health risks including lung cancer and cardiovascular disease.',
    consensus_level: 'STRONG',
    claim_direction: 'harmful',
    typical_claim_direction: 'harmful'
  }
};

const detectedConsensus = Object.entries(INSTITUTIONAL_CONSENSUS_DOMAINS)
  .filter(([, d]) => d.matches)
  .map(([key, d]) => ({
    domain: key,
    institutions: d.institutions,
    consensus_statement: d.consensus_statement,
    consensus_level: d.consensus_level,
    claim_direction: d.claim_direction,
    typical_claim_direction: d.typical_claim_direction,
    contradicts_typical_claim: d.claim_direction !== d.typical_claim_direction && d.typical_claim_direction !== 'safe'
  }));

const hasInstitutionalConsensus = detectedConsensus.length > 0;

const levelOrder = ['VERY_STRONG', 'STRONG', 'MODERATE', 'WEAK', 'UNKNOWN'];
const institutionalConsensusStrength = detectedConsensus.length > 0
  ? detectedConsensus.reduce((best, d) =>
      levelOrder.indexOf(d.consensus_level) < levelOrder.indexOf(best)
        ? d.consensus_level : best
    , 'WEAK')
  : null;

const institutionalContradictsClaim = detectedConsensus.some(d => d.contradicts_typical_claim);

let consensus_level_forced = null;
let consensus_level_forced_reason = '';

if (hasInstitutionalConsensus && institutionalContradictsClaim) {
  if (institutionalConsensusStrength === 'VERY_STRONG') {
    consensus_level_forced = 'STRONG';
    consensus_level_forced_reason = 'OVERRIDE: Consenso institucional VERY_STRONG (IARC/WHO) contradice el claim. El consenso de los artículos es irrelevante frente al consenso institucional establecido.';
  } else if (institutionalConsensusStrength === 'STRONG') {
    consensus_level_forced = 'STRONG';
    consensus_level_forced_reason = 'OVERRIDE: Consenso institucional STRONG contradice el claim. Los artículos recuperados no pueden anular el consenso establecido.';
  } else if (institutionalConsensusStrength === 'MODERATE') {
    consensus_level_forced = 'MODERATE';
    consensus_level_forced_reason = 'Consenso institucional MODERATE contradice el claim. Considerar en la evaluación final.';
  }
}

let institutional_consensus_instruction = '';
if (hasInstitutionalConsensus) {
  const strong = detectedConsensus.filter(d =>
    ['VERY_STRONG', 'STRONG'].includes(d.consensus_level));
  const weak = detectedConsensus.filter(d =>
    ['WEAK', 'UNKNOWN'].includes(d.consensus_level));

  if (strong.length > 0) {
    const domains = strong.map(d =>
      `${d.domain} [${d.institutions.join('/')}]: ${d.consensus_statement}`
    ).join(' | ');

    if (institutionalContradictsClaim) {
      institutional_consensus_instruction =
        `INSTITUTIONAL CONSENSUS OVERRIDE (${institutionalConsensusStrength}): ${domains}. ` +
        `CRITICAL: This institutional consensus DIRECTLY CONTRADICTS the claim's direction. ` +
        `The claim says something is beneficial/protective, but IARC/WHO classify the exposure as carcinogenic/harmful. ` +
        `You MUST set consensus_level to STRONG (reflecting the institutional consensus, NOT the articles). ` +
        `The verdict should be EXAGERADO or FALSE with HIGH confidence, because the claim contradicts established scientific consensus. ` +
        `Do NOT let article-level consensus (which may be MIXED due to limited retrieval) override institutional consensus.`;
    } else {
      institutional_consensus_instruction =
        `INSTITUTIONAL CONSENSUS DETECTED (${institutionalConsensusStrength}): ${domains}. ` +
        `This consensus is independent of the retrieved articles. ` +
        `Even if articles are inconclusive or tangential, this institutional consensus should be considered as high-priority background context, but the final verdict must still depend on claim wording, scope, and retrieved evidence.`;
    }
  }

  if (weak.length > 0) {
    const domains = weak.map(d =>
      `${d.domain}: ${d.consensus_statement}`
    ).join(' | ');
    institutional_consensus_instruction +=
      ` WEAK/NO CONSENSUS NOTE: ${domains}.`;
  }
}

const consensus_layers = {
  article_evidence_consensus: null,
  institutional_consensus: {
    detected: hasInstitutionalConsensus,
    domains: detectedConsensus,
    strongest_level: institutionalConsensusStrength,
    instruction: institutional_consensus_instruction,
    contradicts_claim: institutionalContradictsClaim,
    consensus_level_forced: consensus_level_forced,
    consensus_level_forced_reason: consensus_level_forced_reason
  },
